using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.SupplierReceipts;public class IndexModel(ApplicationDbContext db,IPermissionService permissions):PageModel
{
 public IReadOnlyList<SupplierReceipt> Items{get;private set;}=[];[BindProperty(SupportsGet=true)]public string? Search{get;set;}[BindProperty(SupportsGet=true)]public int PageNumber{get;set;}=1;public int TotalPages{get;private set;}public bool CanAdd{get;private set;}public bool CanUpdate{get;private set;}public bool CanDelete{get;private set;}
 public async Task OnGetAsync(){const int size=15;var q=db.SupplierReceipts.Include(x=>x.Supplier).Include(x=>x.Material).ThenInclude(x=>x.UnitOfMeasure).AsNoTracking();if(!string.IsNullOrWhiteSpace(Search))q=q.Where(x=>x.PolicyNumber.Contains(Search)||x.Supplier.Name.Contains(Search)||x.Material.Name.Contains(Search));var count=await q.CountAsync();TotalPages=Math.Max(1,(int)Math.Ceiling(count/(double)size));PageNumber=Math.Clamp(PageNumber,1,TotalPages);Items=await q.OrderByDescending(x=>x.Date).ThenByDescending(x=>x.CreatedAt).Skip((PageNumber-1)*size).Take(size).ToListAsync();CanAdd=await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Add);CanUpdate=await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Update);CanDelete=await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Delete);}
 public async Task<IActionResult> OnPostDeleteAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierReceipts,PermissionAction.Delete))return Forbid();var x=await db.SupplierReceipts.Include(x=>x.Payments).Include(x=>x.CustomerDelivery).SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();if(x.Payments.Count>0||x.CustomerDelivery is not null){TempData["Error"]="لا يمكن حذف استلام مرتبط بدفع أو توريد لعميل.";return RedirectToPage();}x.IsDeleted=true;x.DeletedAt=DateTimeOffset.UtcNow;x.DeletedBy=User.Identity?.Name;await db.SaveChangesAsync();return RedirectToPage();}
}
